# store_key NAME VALUE: keyring에 저장(값은 stdin으로만 넘겨 명령줄·로그에 남지 않게)
store_key() {
  local name="$1" value="$2"
  [[ -z "$value" ]] && { note "건너뜀: $name"; return; }
  if printf '%s' "$value" | uv run python -c "import sys; from nsm.config.secrets import KeyringSecretStore; KeyringSecretStore().set(sys.argv[1], sys.stdin.read())" "$name"; then
    printf '  %s✓ 저장%s %s → Windows 자격 증명 관리자\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("$name 저장 실패: uv run nsm init 으로 다시 입력")
    warn "$name 저장 실패"
  fi
}

